/* Roadmap step 4, the sourcing stage (docs/FINAL_AUDIT.md H-6; owner decisions 128 (b), 130): what kind of claim each narrative
   statement of data.js and analysis.js makes, and the readings it rests on. Guarded data (tools/visual/data-invariance.js, "narrative
   claims"): it changes only with evidence, each change recorded in CHANGELOG.md.
   - The statements are tools/step4/statements.js's, one per string, by ref (the overclaim scan's path format); their inventory is
     docs/step4-evidence/inventory.md, generated by tools/step4/inventory.js.
   - STATEMENT_CLAIMS: ref -> {h, cl, by, note}. A statement without an entry is "unchecked": not yet checked against a source read here.
       h    the first 12 hex digits of the SHA-1 of the statement's text, normalised as the overclaim scan normalises it
            (tools/step4/statements.js hashOf): a reword anywhere in the text fails test.js until its claim is reviewed;
       cl   a key of CLAIM_WORDS other than "unchecked";
       by   [{src, at, rd, side}]: the source (a key of APPEARANCE_SOURCES, the one table of works read), its locator, the reading's id in
            docs/step4-evidence/readings.md or docs/step2-evidence/readings.md (the quotations are there, not in the build), and, for a
            disputed claim, the side the reading supports;
       note optional, in a visitor's words; never a clock time (the hours are the tracks' timings and the chronology ledger's).
   - CLAIM_WORDS: each claim's word and its one-line definition, as a visitor would be told them; nothing shows them yet (the vocabulary is
     an owner question of step 4). */
var CLAIM_WORDS = {
  fact:          {w:"Read in a source",        d:"A source read here says what the statement says."},
  attributed:    {w:"As a source tells it",    d:"The statement reports, by name, what a source read here says: the claim is that the source says it."},
  disputed:      {w:"The sources disagree",    d:"The sources read here disagree, and the statement names each side."},
  derived:       {w:"Derived",                 d:"Computed from the map's plot, or from figures a source gives."},
  interpretation:{w:"This map's reading",      d:"A reading or an inference of this map, beyond what its sources say."},
  uncertain:     {w:"Not established",         d:"Searched for in the sources read here and not established by them."},
  design:        {w:"Design decision",         d:"A convention of this map's drawing or method, not a claim about the battle."},
  unchecked:     {w:"Not yet checked",         d:"Not yet checked against a source read here."}
};

